import json, shlex, sys

# Illustrative only: denylists are easy to evade. Prefer allowlists, path checks, or sandboxing.
SEPARATORS = {"&&", "||", ";", "|"}

def is_recursive_force_rm(cmd: str) -> bool:
    try:
        tokens = shlex.split(cmd)
    except ValueError:
        return True  # can't parse it -> fail closed
    for i, tok in enumerate(tokens):
        if tok.rsplit("/", 1)[-1] != "rm":
            continue
        short, long = set(), set()
        for arg in tokens[i + 1:]:
            if arg in SEPARATORS:
                break
            if arg.startswith("--"):
                long.add(arg)
            elif arg.startswith("-"):
                short.update(arg[1:])  # -rf, -fr, -r -f, -Rf all land here
        recursive = bool(short & {"r", "R"}) or "--recursive" in long
        force = "f" in short or "--force" in long
        if recursive and force:
            return True
    return False

