import json

TOOLS = {"get_order": get_order, "issue_refund": issue_refund}
NEEDS_APPROVAL = {"issue_refund"}

def run_tool_calls(response, approve):
    results = []
    for block in response.content:
        if block.type != "tool_use":
            continue  # server-tool blocks and text need no dispatch
        try:
            if block.name in NEEDS_APPROVAL and not approve(block):
                out, err = "Declined by a human reviewer.", True
            else:
                out, err = json.dumps(TOOLS[block.name](**block.input)), False
        except Exception as exc:
            out, err = f"{type(exc).__name__}: {exc}", True
        results.append({"type": "tool_result", "tool_use_id": block.id,
                        "content": out, "is_error": err})
    return {"role": "user", "content": results}  # one message for all results

